 class=\"modal-body\" v-if=\"homework.attachment != ''\">\n                                <div class=\"flex\">\n                                    <a :href=\"homework.attachment\" target=\"_blank\">View Attachment</a>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\n\n    export default {\n        props:['url' , 'scope' , 'hidecolumns', 'searchquery' , 'mode'],\n        data () {\n            return {\n                homeworks:[],\n                homework:[],\n                showPast:'',\n                show:'',\n                params:{},\n                errors:[],\n                success:null, \n            }\n        },\n\n        methods:{\n            getData()\n            {\n                axios.get('/'+this.mode+'/homework/show/approved/list/?standardLink_id='+this.scope).then(response => {\n                    this.homeworks  = response.data.data;    \n                    //console.log(this.homeworks);    \n                    //console.log(this.hidecolumns);    \n                });\n            },\n\n            trim(string) \n            {\n                return string.substring(0,140) + '...';\n            },\n\n            showModal(id)\n            {\n                this.show = id+'_show';\n                axios.get('/'+this.mode+'/homework/edit/list/'+id).then(response => {\n                    this.homework = response.data;\n                });\n            },\n\n            closeModal()\n            {\n                this.show = 0;\n            },\n\n            showPastHomework(e)\n            {\n                if (e.target.checked) \n                {\n                    this.params = { showPast:this.showPast };\n\n                    this.final = this.url+'/'+this.mode+'/homework/show/list/?'+this.searchquery;\n\n                    Object.keys(this.params).forEach(key => {\n                      this.final = this.addParam(this.final, key, this.params[key])\n                    });\n\n                    axios.get(this.final).then(response => {\n                      this.homeworks = response.data.data;\n                    });\n                }\n                else if (!e.target.checked)\n                {\n                    this.getData();\n                }\n            },\n\n            addParam(url, param, value) \n            {\n                param = encodeURIComponent(param);\n                var r = \"([&?]|&amp;)\" + param + \"\\\\b(?:=(?:[^&#]*))*\";\n                var a = document.createElement('a');\n                var regex = new RegExp(r);\n                var str = param + (value ? \"=\" + encodeURIComponent(value) : \"\"); \n                a.href = url;\n                var q = a.search.replace(regex, \"$1\"+str);\n                if (q === a.search) \n                {\n                    a.search += (a.search ? \"&\" : \"\") + str;\n                } \n                else \n                {\n                    a.search = q;\n                }\n                return a.href ;\n            },\n\n            deleteHomework(id) \n            {\n                var thisswal = this;\n                Swal.fire({\n                    title: 'Are you sure',\n                    text: 'Do you want to delete this Home work ?',\n                    icon: \"info\",\n                    showCancelButton: true,\n                    confirmButtonText: 'Yes',\n                    cancelButtonText: 'No',\n                    \n                }).then(function(result) {\n                    if (result.isConfirmed) \n                    {\n                        axios.get(thisswal.url+ '/'+thisswal.mode+'/homework/delete/'+ id).then(response => {\n                            thisswal.success = response.data.success;\n                            window.location.reload();\n                        }); \n                    }\n                    else \n                    {\n                        Swal.fire(\"Cancelled\");\n                    }\n                });\n            },\n        },\n  \n        created()\n        {   \n            this.getData();\n        }\n    }\n</script>\n\n<style scoped>\n    .modal-mask {\n        position: fixed;\n        z-index: 9998;\n        top: 0;\n        left: 0;\n        width: 100%;\n        height: 100%;\n        background-color: rgba(0, 0, 0, .5);\n        display: table;\n        transition: opacity .3s ease;\n    }\n\n    .modal-wrapper {\n        display: table-cell;\n        vertical-align: middle;\n        overflow:auto;\n    }\n\n    .modal-container-new {\n        margin: 0px auto;\n        /*padding: 20px 30px;*/\n        background-color: #fff;\n        border-radius: 2px;\n        box-shadow: 0 2px 8px rgba(0, 0, 0, .33);\n        transition: all .3s ease;\n        height: 500px;\n        overflow:auto;\n    }\n\n    .modal-container {\n        margin: 0px auto;\n        /*padding: 20px 30px;*/\n        background-color: #fff;\n        border-radius: 2px;\n        box-shadow: 0 2px 8px rgba(0, 0, 0, .33);\n        transition: all .3s ease;\n        /*height: 500px;*/\n        overflow:auto;\n    }\n\n    .modal-header h3 {\n        margin-top: 0;\n        color: #42b983;\n    }\n\n    .modal-body {\n        margin: 20px 0;\n    }\n\n    .modal-default-button {\n        float: right;\n    }\n\n    /*\n     * The following styles are auto-applied to elements with\n     * transition=\"modal\" when their visibility is toggled\n     * by Vue.js.\n     *\n     * You can easily play with the modal transition by editing\n     * these styles.\n     */\n    .modal-enter {\n        opacity: 0;\n    }\n\n    .modal-leave-active {\n        opacity: 0;\n    }\n\n    .modal-enter .modal-container,\n    .modal-leave-active .modal-container {\n        -webkit-transform: scale(1.1);\n        transform: scale(1.1);\n    }